<section class="admin-head"><div><p class="eyebrow">MakeOS · v0.7.2</p><h1>Procurement & Inventory</h1><p>Suppliers, raw-material masters, purchase orders, GRNs, lots and stock availability.</p></div></section>
<div class="admin-grid two">
<section class="admin-card"><h2>Add supplier</h2><form method="post" action="<?=e(url('/admin/procurement/supplier'))?>" class="stack"><?=csrf_field()?><label>Name<input name="name" required></label><label>Email<input type="email" name="email"></label><label>Phone<input name="phone"></label><label>GSTIN<input name="gstin"></label><label>Lead time (days)<input type="number" min="0" name="lead_days" value="7"></label><button class="btn primary">Save supplier</button></form></section>
<section class="admin-card"><h2>Add material</h2><form method="post" action="<?=e(url('/admin/procurement/material'))?>" class="stack"><?=csrf_field()?><label>Code<input name="code" placeholder="WOOD-ASH-25"></label><label>Name<input name="name" required></label><label>Type<select name="type"><option>MATERIAL</option><option>HARDWARE</option><option>FINISH</option><option>PACKAGING</option></select></label><label>Unit<input name="unit" value="sq.ft" required></label><label>Reorder level<input type="number" step="0.01" min="0" name="reorder_level" value="0"></label><label>Preferred supplier<select name="preferred_supplier_guid"><option value="">—</option><?php foreach($suppliers as $s):?><option value="<?=e($s['guid'])?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><button class="btn primary">Save material</button></form></section>
</div>
<section class="admin-card"><h2>Stock ledger</h2><div class="table-wrap"><table><thead><tr><th>Material</th><th>Available</th><th>Reserved</th><th>Value</th><th>Reorder</th></tr></thead><tbody><?php foreach($stock as $row):?><tr><td><?=e($row['material']['code'])?> · <?=e($row['material']['name'])?></td><td><?=e((string)$row['available'])?> <?=e($row['material']['unit'])?></td><td><?=e((string)$row['reserved'])?></td><td><?=money($row['stock_value'])?></td><td><?=$row['below_reorder']?'<strong>LOW</strong>':'OK'?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="admin-card"><h2>Create purchase order</h2><?php if(!$suppliers||!$materials):?><p>Add at least one supplier and material first.</p><?php else:?><form method="post" action="<?=e(url('/admin/procurement/po'))?>" class="stack"><?=csrf_field()?><label>Supplier<select name="supplier_guid" required><?php foreach($suppliers as $s):?><option value="<?=e($s['guid'])?>"><?=e($s['name'])?></option><?php endforeach;?></select></label><div class="admin-grid three"><?php for($i=0;$i<3;$i++):?><label>Material <?=$i+1?><select name="material_guid[]"><option value="">—</option><?php foreach($materials as $m):?><option value="<?=e($m['guid'])?>"><?=e($m['code'].' · '.$m['name'])?></option><?php endforeach;?></select></label><label>Qty<input type="number" step="0.01" min="0" name="qty[]"></label><label>Unit cost ₹<input type="number" min="0" name="unit_cost[]"></label><?php endfor;?></div><label>Notes<textarea name="notes"></textarea></label><button class="btn primary">Create PO</button></form><?php endif;?></section>
<section class="admin-card"><h2>Purchase orders</h2><div class="table-wrap"><table><thead><tr><th>PO</th><th>Supplier</th><th>Status</th><th>Total</th><th>Action / receive</th></tr></thead><tbody><?php foreach($pos as $po):?><tr><td><?=e($po['number'])?></td><td><?=e($po['supplier_snapshot']['name'])?></td><td><?=e($po['status'])?></td><td><?=money($po['total'])?></td><td><?php if($po['status']==='DRAFT'):?><form method="post" action="<?=e(url('/admin/procurement/po/'.$po['guid'].'/issue'))?>"><?=csrf_field()?><button class="btn outline">Issue</button></form><?php elseif(in_array($po['status'],['ISSUED','PART_RECEIVED'],true)):?><form method="post" action="<?=e(url('/admin/procurement/po/'.$po['guid'].'/receive'))?>" class="stack"><?=csrf_field()?><?php foreach($po['lines'] as $l):?><label><?=e($l['material_name'])?> (balance <?=e((string)($l['qty_ordered']-$l['qty_received']))?>)<input type="number" step="0.01" min="0" max="<?=e((string)($l['qty_ordered']-$l['qty_received']))?>" name="received[<?=e($l['guid'])?>]" value="0"></label><?php endforeach;?><input name="delivery_ref" placeholder="Supplier challan / invoice"><button class="btn outline">Receive GRN</button></form><?php else:?>Closed<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
